FUNCTION_BLOCK FB_S04
VAR_INPUT
    RawWeight : INT;
    ZeroBtn : BOOL;
    CalibWeight : REAL;
END_VAR
VAR_OUTPUT
    CompensatedWeight : REAL;
    ZeroOffset : INT;
    DriftAlarm : BOOL;
    Status : WORD;
END_VAR
VAR
    ZeroBtnLast : BOOL := FALSE;
    InitDone : BOOL := FALSE;
    Delta : DINT;
END_VAR

(*
  Reported semantic conflicts retained:
  1) K3/C6 hysteresis vs C2: DriftAlarm is held between |Delta| = 150 and 200,
     while C2 states G(DriftAlarm -> driftOut) with driftOut at |Delta| >= 200.
     This implementation follows the explicit hysteresis K3/C6.
  2) C4 every-scan conversion vs initial_state/C10 first-cycle compensation:
     first scan is initialized to CompensatedWeight = 0.0; C4 is applied thereafter.
  3) First-scan ZeroBtn edge is suppressed to keep C10 ZeroOffset = 0 on the first scan.
*)

IF NOT InitDone THEN
    ZeroOffset := 0;
    CompensatedWeight := 0.0;
    DriftAlarm := FALSE;
    Status := 16#0000;
    ZeroBtnLast := ZeroBtn;  (* suppress power-up edge; keep first-cycle ZeroOffset = 0 *)
    InitDone := TRUE;
ELSE
    (* K1: ZeroBtn rising edge calibrates zero point and clears drift alarm. *)
    IF ZeroBtn AND NOT ZeroBtnLast THEN
        ZeroOffset := RawWeight;
        DriftAlarm := FALSE;
    END_IF;
    ZeroBtnLast := ZeroBtn;

    (* K2/C4: compensated weight, DINT subtraction avoids INT overflow. *)
    Delta := INT_TO_DINT(RawWeight) - INT_TO_DINT(ZeroOffset);
    CompensatedWeight := DINT_TO_REAL(Delta) * 0.01;

    (* K3: drift alarm with 50-unit hysteresis. Formal driftOut uses >= 200. *)
    IF DriftAlarm THEN
        IF (Delta <= 150) AND (Delta >= -150) THEN
            DriftAlarm := FALSE;
        END_IF;
    ELSE
        IF (Delta >= 200) OR (Delta <= -200) THEN
            DriftAlarm := TRUE;
        END_IF;
    END_IF;

    (* Status priority: out-of-range 8402, drift 8401, normal 0000.
       For IEC INT, the 8402 condition is unreachable but retained per requirement. *)
    IF (RawWeight > 32767) OR (RawWeight < -32768) THEN
        Status := 16#8402;
    ELSIF DriftAlarm THEN
        Status := 16#8401;
    ELSE
        Status := 16#0000;
    END_IF;
END_IF;

END_FUNCTION_BLOCK
